external::log
            .entries()
            .iter()
            .map(|e| AuditEntry {
                seq: e.seq,
                ts: e.ts.clone(),
                op: e.op.clone(),
                payload: if e.seq == 2 {
                    r#"{"id":"ATTACKER"}"#.to_string()
                } else {
                    e.payload.clone()
                },
                prev_hash: e.prev_hash.clone(),
                hash: e.hash.clone(),
            })
            .collect

